import { dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import { FlatCompat } from '@eslint/eslintrc'

// ESLint 9 only reads flat config, so the old .eslintrc.json was silently
// never loaded and `npm run lint` failed before checking anything.
// eslint-config-next 15 still ships in the legacy format; FlatCompat adapts
// it without changing the rules.
const compat = new FlatCompat({ baseDirectory: dirname(fileURLToPath(import.meta.url)) })

const config = [
  {
    // Generated by Payload, not written by hand.
    ignores: ['.next/', 'src/app/(payload)/admin/importMap.js', 'src/payload-types.ts'],
  },
  ...compat.extends('next/core-web-vitals'),
]

export default config
